insert into public.catalysts (id, name, emoji, flavor) values
  ('heat', 'Heat', '🔥', 'You bring the fire. Half this lab is waiting on you.'),
  ('pressure', 'Pressure', '🗜️', 'You squeeze until it happens.'),
  ('light', 'Light', '☀️', 'You are literally the sun.'),
  ('electricity', 'Electricity', '⚡', 'You split what others can''t.'),
  ('enzyme', 'Enzyme', '🧬', 'You''re the living shortcut. Yeast respects you.'),
  ('acid', 'Acid', '🧪', 'You dissolve the impossible.')
