insert into public.compounds (id, name, formula, recipe, catalyst, tier, points, riddle, locked_hint) values
  ('water', 'Water', 'H₂O', '{"H":2,"O":1}'::jsonb, null, 'basic', 5, 'You drink me, swim in me, and you''re about 60% me. Two tinies, one breath.', null),
  ('carbon-dioxide', 'Carbon Dioxide', 'CO₂', '{"C":1,"O":2}'::jsonb, null, 'basic', 5, 'I''m the fizz in your soda and the sigh you just let out. One pencil, two breaths.', null),
  ('carbon-monoxide', 'Carbon Monoxide', 'CO', '{"C":1,"O":1}'::jsonb, null, 'basic', 5, 'Silent, invisible, and the reason your ceiling has an alarm. I''m my fizzy sibling with one breath missing.', null),
  ('methane', 'Methane', 'CH₄', '{"C":1,"H":4}'::jsonb, null, 'basic', 5, 'Cows burp me, kitchens burn me. One pencil with four tinies huddled round it.', null),
  ('salt', 'Table Salt', 'NaCl', '{"Na":1,"Cl":1}'::jsonb, null, 'basic', 5, 'Salt''s metal explodes in water. The green gas is poison. Put them together and you sprinkle the result on fries.', null),
  ('hydrochloric-acid', 'Hydrochloric Acid', 'HCl', '{"H":1,"Cl":1}'::jsonb, null, 'basic', 5, 'Your stomach is full of me right now. One tiny, one green gas. Don''t lick the bench.', null),
  ('sodium-hydroxide', 'Sodium Hydroxide', 'NaOH', '{"Na":1,"O":1,"H":1}'::jsonb, null, 'basic', 5, 'Soap-makers and drain-unblockers love me. One each of salt''s metal, the breath and a tiny.', null),
  ('quicklime', 'Quicklime', 'CaO', '{"Ca":1,"O":1}'::jsonb, null, 'basic', 5, 'The bone-builder takes one breath and turns into old-school builders'' mortar.', null),
  ('chalk', 'Chalk / Limestone', 'CaCO₃', '{"Ca":1,"C":1,"O":3}'::jsonb, null, 'basic', 5, 'Your teacher wrote with me and cliffs are made of me. Bone-builder, pencil, three breaths.', null),
  ('hydrogen-sulfide', 'Hydrogen Sulfide', 'H₂S', '{"H":2,"S":1}'::jsonb, null, 'basic', 5, 'I smell exactly like rotten eggs. I''m water''s evil twin: keep the two tinies, swap the breath for the yellow one.', null),
  ('sulfur-dioxide', 'Sulfur Dioxide', 'SO₂', '{"S":1,"O":2}'::jsonb, null, 'basic', 5, 'Volcanoes burp me and acid rain starts with me. The yellow one, holding two breaths.', null),
  ('nitrogen-dioxide', 'Nitrogen Dioxide', 'NO₂', '{"N":1,"O":2}'::jsonb, null, 'basic', 5, 'The brown haze hanging over a traffic jam. One air, two breaths.', null),
  ('laughing-gas', 'Laughing Gas', 'N₂O', '{"N":2,"O":1}'::jsonb, null, 'basic', 5, 'Dentists use me and you giggle. Two airs, one breath.', null),
  ('baking-soda', 'Baking Soda', 'NaHCO₃', '{"Na":1,"H":1,"C":1,"O":3}'::jsonb, null, 'basic', 5, 'Science-fair volcanoes and fluffy cakes need me. Four different ingredients, and the breath shows up three times.', null),
  ('calcium-chloride', 'Calcium Chloride', 'CaCl₂', '{"Ca":1,"Cl":2}'::jsonb, null, 'basic', 5, 'Thrown on icy roads and packed into wardrobe damp-catchers. One bone-builder, two green gases.', null),
  ('ammonia', 'Ammonia', 'NH₃', '{"N":1,"H":3}'::jsonb, 'pressure', 'catalyzed', 20, 'I feed half the world as fertilizer and I smell like cleaning day. One air, three tinies, and they won''t hold hands unless somebody squeezes.', 'N ×1 · H ×3 · catalyst: PRESSURE'),
  ('hydrogen-peroxide', 'Hydrogen Peroxide', 'H₂O₂', '{"H":2,"O":2}'::jsonb, 'electricity', 'catalyzed', 18, 'Water with one breath too many. I bleach hair and fizz on cuts. Forcing in that extra breath takes a jolt.', 'H ×2 · O ×2 · catalyst: ELECTRICITY'),
  ('ozone', 'Ozone', 'O₃', '{"O":3}'::jsonb, 'light', 'catalyzed', 18, 'I''m the sky''s sunscreen. Breath, breath, breath, and only sunlight can stitch the three together.', 'O ×3 · catalyst: LIGHT'),
  ('glucose', 'Glucose', 'C₆H₁₂O₆', '{"C":6,"H":12,"O":6}'::jsonb, 'light', 'catalyzed', 25, 'Every leaf on campus is cooking me right now. Six, twelve, six, plus the leaves'' secret ingredient.', 'C ×6 · H ×12 · O ×6 · catalyst: LIGHT'),
  ('sucrose', 'Table Sugar', 'C₁₂H₂₂O₁₁', '{"C":12,"H":22,"O":11}'::jsonb, 'light', 'catalyzed', 28, 'Your chai needs two spoons of me. Twelve pencils, twenty-two tinies, eleven breaths, grown by sugarcane in full sun.', 'C ×12 · H ×22 · O ×11 · catalyst: LIGHT'),
  ('ethanol', 'Ethanol', 'C₂H₆O', '{"C":2,"H":6,"O":1}'::jsonb, 'enzyme', 'catalyzed', 22, 'Yeast makes me out of sugar, and hand sanitizer is mostly me. Two pencils, six tinies, one breath, and something alive has to help.', 'C ×2 · H ×6 · O ×1 · catalyst: ENZYME'),
  ('acetic-acid', 'Vinegar (Acetic Acid)', 'C₂H₄O₂', '{"C":2,"H":4,"O":2}'::jsonb, 'enzyme', 'catalyzed', 22, 'I''m the sour in salt-and-vinegar chips. Bacteria turn old wine into me. Two, four, two.', 'C ×2 · H ×4 · O ×2 · catalyst: ENZYME'),
  ('sulfuric-acid', 'Sulfuric Acid', 'H₂SO₄', '{"H":2,"S":1,"O":4}'::jsonb, 'heat', 'catalyzed', 22, 'Car batteries are full of me and I eat holes in jeans. Two tinies, one yellow, four breaths, forged in fire.', 'H ×2 · S ×1 · O ×4 · catalyst: HEAT'),
  ('nitric-acid', 'Nitric Acid', 'HNO₃', '{"H":1,"N":1,"O":3}'::jsonb, 'heat', 'catalyzed', 22, 'Rocket fuel and fertilizer both start with me. One tiny, one air, three breaths, cooked into being.', 'H ×1 · N ×1 · O ×3 · catalyst: HEAT'),
  ('ethylene', 'Ethylene', 'C₂H₄', '{"C":2,"H":4}'::jsonb, 'heat', 'catalyzed', 18, 'I ripen bananas, and every plastic bag starts life as me. Two and four, but only with the fire turned up.', 'C ×2 · H ×4 · catalyst: HEAT'),
  ('bleach', 'Bleach', 'NaClO', '{"Na":1,"Cl":1,"O":1}'::jsonb, 'electricity', 'catalyzed', 18, 'Table salt plus one breath, but only if you zap salty water first. Your white shirts owe me.', 'Na ×1 · Cl ×1 · O ×1 · catalyst: ELECTRICITY'),
  ('urea', 'Urea', 'CH₄N₂O', '{"C":1,"H":4,"N":2,"O":1}'::jsonb, 'pressure', 'catalyzed', 25, 'Yes, I''m in pee. I was also the first ''living'' chemical ever made in a lab. Ammonia''s ingredients plus a pencil and a breath, squeezed hard.', 'C ×1 · H ×4 · N ×2 · O ×1 · catalyst: PRESSURE'),
  ('caffeine', 'Caffeine', 'C₈H₁₀N₄O₂', '{"C":8,"H":10,"N":4,"O":2}'::jsonb, 'enzyme', 'catalyzed', 35, 'Exam week runs on me. Coffee plants build me: eight, ten, four, two.', 'C ×8 · H ×10 · N ×4 · O ×2 · catalyst: ENZYME'),
  ('aspirin', 'Aspirin', 'C₉H₈O₄', '{"C":9,"H":8,"O":4}'::jsonb, 'acid', 'catalyzed', 35, 'Headache? Willow bark had my great-grandparent. Nine, eight, four, and a sour shove.', 'C ×9 · H ×8 · O ×4 · catalyst: ACID'),
  ('ester-banana', 'Banana Flavour (Isoamyl Acetate)', 'C₇H₁₄O₂', '{"C":7,"H":14,"O":2}'::jsonb, 'acid', 'catalyzed', 30, 'Fake banana candy tastes like me. Real bananas, less so. Seven, fourteen, two, and an acid has to set us up.', 'C ×7 · H ×14 · O ×2 · catalyst: ACID'),
  ('potassium-chloride', 'Potassium Chloride', 'KCl', '{"K":1,"Cl":1}'::jsonb, null, 'uncommon', 12, 'Low-sodium salt is secretly me. The banana metal meets the green gas.', null),
  ('saltpeter', 'Saltpeter', 'KNO₃', '{"K":1,"N":1,"O":3}'::jsonb, null, 'uncommon', 12, 'The bang in a firework. Banana metal, one air, three breaths.', null),
  ('rust', 'Rust', 'Fe₂O₃', '{"Fe":2,"O":3}'::jsonb, null, 'uncommon', 12, 'Every abandoned bicycle on campus is wearing me. Two blood metals, three breaths.', null),
  ('copper-sulfate', 'Copper Sulfate', 'CuSO₄', '{"Cu":1,"S":1,"O":4}'::jsonb, null, 'uncommon', 12, 'Brilliant blue crystals from your school lab. The penny metal, the yellow one, four breaths.', null),
  ('sand', 'Sand / Quartz', 'SiO₂', '{"Si":1,"O":2}'::jsonb, null, 'uncommon', 12, 'Dubai has a LOT of me. The chip-maker, holding two breaths.', null),
  ('phosphoric-acid', 'Phosphoric Acid', 'H₃PO₄', '{"H":3,"P":1,"O":4}'::jsonb, null, 'uncommon', 12, 'The tang in cola. Three tinies, one matchstick, four breaths.', null),
  ('sodium-fluoride', 'Sodium Fluoride', 'NaF', '{"Na":1,"F":1}'::jsonb, null, 'uncommon', 12, 'Your toothpaste''s secret weapon. Salt''s metal, but swap the green gas for the angriest one.', null),
  ('epsom-salt', 'Epsom Salt', 'MgSO₄', '{"Mg":1,"S":1,"O":4}'::jsonb, null, 'uncommon', 12, 'Sore muscles soak in me. The flash metal, the yellow one, four breaths.', null),
  ('magnesium-oxide', 'Magnesium Oxide', 'MgO', '{"Mg":1,"O":1}'::jsonb, 'heat', 'uncommon', 20, 'Light me and I burn blinding white, then leave white ash. Flash metal, one breath, fire.', 'Mg ×1 · O ×1 · catalyst: HEAT'),
  ('alumina', 'Alumina (Sapphire)', 'Al₂O₃', '{"Al":2,"O":3}'::jsonb, 'heat', 'uncommon', 22, 'Add a pinch of impurity and I''m a sapphire. Two soda-can metals, three breaths, one furnace.', 'Al ×2 · O ×3 · catalyst: HEAT'),
  ('pyrite', 'Fool''s Gold (Pyrite)', 'FeS₂', '{"Fe":1,"S":2}'::jsonb, 'heat', 'uncommon', 22, 'I look like treasure. I''m not. One blood metal, two yellows, cooked deep underground.', 'Fe ×1 · S ×2 · catalyst: HEAT'),
  ('bone-mineral', 'Bone Mineral', 'Ca₃(PO₄)₂', '{"Ca":3,"P":2,"O":8}'::jsonb, 'enzyme', 'uncommon', 28, 'You''re holding your phone with me. Three bone-builders, two matchsticks, eight breaths, and your body''s own machinery.', 'Ca ×3 · P ×2 · O ×8 · catalyst: ENZYME'),
  ('teflon', 'Teflon (monomer)', 'C₂F₄', '{"C":2,"F":4}'::jsonb, 'pressure', 'uncommon', 30, 'Nothing sticks to me, not even eggs. Two pencils, four angriest ones, squeezed hard.', 'C ×2 · F ×4 · catalyst: PRESSURE'),
  ('lithium-carbonate', 'Lithium Carbonate', 'Li₂CO₃', '{"Li":2,"C":1,"O":3}'::jsonb, null, 'rare', 35, 'Every phone battery starts life as me. Two lightest metals, a pencil, three breaths.', null),
  ('zinc-oxide', 'Zinc Oxide', 'ZnO', '{"Zn":1,"O":1}'::jsonb, null, 'rare', 30, 'The white stuff on a lifeguard''s nose. The armour metal, one breath.', null),
  ('silver-nitrate', 'Silver Nitrate', 'AgNO₃', '{"Ag":1,"N":1,"O":3}'::jsonb, null, 'rare', 35, 'Election ink that won''t wash off your finger. The mirror metal, one air, three breaths.', null),
  ('potassium-iodide', 'Potassium Iodide', 'KI', '{"K":1,"I":1}'::jsonb, null, 'rare', 30, 'The pills you take in a radiation emergency. The banana metal meets the purple one.', null),
  ('silver-chloride', 'Silver Chloride', 'AgCl', '{"Ag":1,"Cl":1}'::jsonb, 'light', 'rare', 45, 'Old film photos were made of me: I darken when the world looks at me. Mirror metal, green gas, and a flash.', 'Ag ×1 · Cl ×1 · catalyst: LIGHT'),
  ('silver-iodide', 'Silver Iodide', 'AgI', '{"Ag":1,"I":1}'::jsonb, 'pressure', 'rare', 50, 'The UAE fires me into clouds to make it rain. Mirror metal and the purple one, packed tight.', 'Ag ×1 · I ×1 · catalyst: PRESSURE'),
  ('gold-chloride', 'Gold Chloride', 'AuCl₃', '{"Au":1,"Cl":3}'::jsonb, 'acid', 'rare', 55, 'The treasure refuses to dissolve in anything except one ridiculous acid cocktail. One treasure, three green gases, the strongest sour.', 'Au ×1 · Cl ×3 · catalyst: ACID'),
  ('lifepo4', 'Lithium Iron Phosphate', 'LiFePO₄', '{"Li":1,"Fe":1,"P":1,"O":4}'::jsonb, 'electricity', 'rare', 60, 'Electric cars run on me. Lightest metal, blood metal, matchstick, four breaths, then charge it up.', 'Li ×1 · Fe ×1 · P ×1 · O ×4 · catalyst: ELECTRICITY'),
  ('zinc-battery', 'Zinc Chloride', 'ZnCl₂', '{"Zn":1,"Cl":2}'::jsonb, 'electricity', 'rare', 45, 'I live inside the cheap batteries in your TV remote. Armour metal, two green gases, a spark.', 'Zn ×1 · Cl ×2 · catalyst: ELECTRICITY'),
  ('heavy-water', 'Heavy Water', 'D₂O', '{"D":2,"O":1}'::jsonb, 'electricity', 'isotope', 90, 'I look exactly like water, but an ice cube of me sinks. Two heavy tinies, one breath, pulled apart by a current.', 'D ×2 · O ×1 · catalyst: ELECTRICITY'),
  ('radiocarbon-co2', 'Radiocarbon CO₂', '¹⁴CO₂', '{"C14":1,"O":2}'::jsonb, null, 'isotope', 70, 'Archaeologists date mummies by me. The ticking pencil, holding two breaths.', null),
  ('heavy-oxygen-water', 'Heavy-Oxygen Water', 'H₂¹⁸O', '{"H":2,"O18":1}'::jsonb, null, 'isotope', 70, 'Hospitals use me to light up body scans. Two ordinary tinies, one heavy breath.', null),
  ('uranium-hexafluoride', 'Uranium Hexafluoride', 'UF₆', '{"U235":1,"F":6}'::jsonb, 'heat', 'isotope', 120, 'The most dangerous thing in this game. One heavyweight, six angriest ones, white-hot.', 'U-235 ×1 · F ×6 · catalyst: HEAT'),
  ('chlorophyll', 'Chlorophyll a', 'C₅₅H₇₂MgN₄O₅', '{"C":55,"H":72,"Mg":1,"N":4,"O":5}'::jsonb, 'light', 'legendary', 100, 'Every green thing on Earth wears me. A huge ring with a flash-metal heart: fifty-five, seventy-two, one, four, five. Sunlight only.', 'C ×55 · H ×72 · Mg ×1 · N ×4 · O ×5 · catalyst: LIGHT'),
  ('heme', 'Heme', 'C₃₄H₃₂FeN₄O₄', '{"C":34,"H":32,"Fe":1,"N":4,"O":4}'::jsonb, 'enzyme', 'legendary', 100, 'I''m why your blood is red. Chlorophyll''s cousin, but my heart is the blood metal. Thirty-four, thirty-two, one, four, four.', 'C ×34 · H ×32 · Fe ×1 · N ×4 · O ×4 · catalyst: ENZYME')
